//! Offline, bounded validation before a separately controlled Filebeat handoff.
//!
//! IDs bind a claimed source digest to a rule, not to an authenticated source.
//! This gate cannot establish that an export was generated by the detector. A
//! trusted operator must retain raw evidence and anchors outside the SIEM index.
use anyhow::{ensure, Result};
use chrono::DateTime;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;

pub const MAX_INPUT_BYTES: usize = 16 * 1024 * 1024;
pub const MAX_RECORD_BYTES: usize = 16 * 1024;
pub const MAX_RECORDS: usize = 20_000;
const SCOPE: &str = "rule signal; no confirmed compromise or transaction-success inference";

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct Export {
    #[serde(rename = "@timestamp")]
    timestamp: String,
    ecs: Ecs,
    event: Event,
    rule: Rule,
    postgres_audit_guard: Guard,
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct Ecs {
    version: String,
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct Event {
    kind: String,
    category: Vec<String>,
    #[serde(rename = "type")]
    types: Vec<String>,
    outcome: String,
    module: String,
    dataset: String,
    id: String,
    hash: String,
    action: String,
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct Rule {
    id: String,
    name: String,
    version: String,
    license: String,
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct Guard {
    schema: String,
    severity: String,
    sqlstate: String,
    raw_sql_included: bool,
    scope: String,
}

fn digest(bytes: &[u8]) -> String {
    hex::encode(Sha256::digest(bytes))
}

fn is_digest(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

impl Export {
    fn validate(&self) -> Result<()> {
        ensure!(
            self.timestamp.len() <= 64 && DateTime::parse_from_rfc3339(&self.timestamp).is_ok(),
            "Timestamp must be an RFC3339 instant"
        );
        ensure!(self.ecs.version == "8.17.0", "Unsupported ECS version");
        ensure!(
            self.event.kind == "alert"
                && self.event.category == ["database"]
                && self.event.types == ["info"]
                && matches!(self.event.outcome.as_str(), "failure" | "unknown")
                && self.event.module == "postgres_audit_guard"
                && self.event.dataset == "postgres_audit_guard.postgresql",
            "Unsupported ECS event fields"
        );
        ensure!(
            self.postgres_audit_guard.schema == "ecs-export/v1"
                && !self.postgres_audit_guard.raw_sql_included
                && self.postgres_audit_guard.scope == SCOPE,
            "Unsupported export schema or privacy fields"
        );
        let state = &self.postgres_audit_guard.sqlstate;
        ensure!(
            state.is_empty()
                || (state.len() == 5
                    && state
                        .bytes()
                        .all(|b| b.is_ascii_uppercase() || b.is_ascii_digit())),
            "SQLSTATE must be empty or a five-character PostgreSQL code"
        );
        let (name, severity) = match self.rule.id.as_str() {
            "DB001" => ("Privileged role option observed", "high"),
            "DB002" => ("Sensitive privilege grant observed", "high"),
            "DB003" => ("Server-program export observed", "high"),
            "DB004" => ("Sensitive data export observed", "high"),
            "DB005" => ("Logging reduction setting observed", "high"),
            "DB006" => ("Permission or authentication failure observed", "medium"),
            "DB900" => ("SQL analysis coverage limitation", "warning"),
            _ => anyhow::bail!("Unsupported detector rule"),
        };
        ensure!(
            self.rule.name == name
                && self.postgres_audit_guard.severity == severity
                && self.rule.version == "0.1.0"
                && self.rule.license == "MIT"
                && self.event.action == self.rule.id,
            "Rule metadata does not match the supported detector policy"
        );
        ensure!(
            self.rule.id != "DB006" || matches!(state.as_str(), "42501" | "28P01" | "28000"),
            "Permission signal requires a matching SQLSTATE"
        );
        ensure!(
            is_digest(&self.event.hash)
                && is_digest(&self.event.id)
                && self.event.id
                    == digest(format!("{}:{}", self.event.hash, self.rule.id).as_bytes()),
            "Document ID does not match the claimed source digest and rule"
        );
        Ok(())
    }
}

#[derive(Debug, Serialize)]
pub struct PrepareSummary {
    pub schema: &'static str,
    pub input_records: usize,
    pub unique_documents: usize,
    pub duplicate_records: usize,
    pub input_sha256: String,
    pub output_sha256: String,
    pub sealed: bool,
    pub note: &'static str,
}

/// Validate a whole bounded export before handing any document to a publisher.
/// Unknown or duplicate JSON fields are rejected by typed serde decoding at every
/// object level; errors deliberately exclude source values and decoder details.
pub fn prepare(input: &[u8]) -> Result<(Vec<u8>, PrepareSummary)> {
    ensure!(
        input.len() <= MAX_INPUT_BYTES,
        "ECS input exceeds byte limit"
    );
    let mut records = 0usize;
    let mut duplicates = 0usize;
    let mut canonical_by_id = BTreeMap::<String, Vec<u8>>::new();
    let mut output = Vec::new();
    for line in input.split_inclusive(|b| *b == b'\n') {
        records += 1;
        ensure!(records <= MAX_RECORDS, "ECS input exceeds record limit");
        ensure!(
            line.len() <= MAX_RECORD_BYTES,
            "ECS record {records} exceeds byte limit"
        );
        let doc: Export = serde_json::from_slice(line).map_err(|_| {
            anyhow::anyhow!("Invalid ECS record {records}: malformed or unsupported fields")
        })?;
        doc.validate()
            .map_err(|error| anyhow::anyhow!("Invalid ECS record {records}: {error}"))?;
        // serde_json::Value uses sorted object keys with the pinned dependency
        // configuration. Whitespace and object member order do not affect equality.
        let mut canonical = serde_json::to_vec(&serde_json::to_value(&doc)?)?;
        canonical.push(b'\n');
        if let Some(prior) = canonical_by_id.get(&doc.event.id) {
            ensure!(
                *prior == canonical,
                "Conflicting payload for repeated document ID at ECS record {records}"
            );
            duplicates += 1;
        } else {
            output.extend_from_slice(&canonical);
            canonical_by_id.insert(doc.event.id, canonical);
        }
    }
    let summary = PrepareSummary {
        schema: "elastic-prepare-result/v1",
        input_records: records,
        unique_documents: canonical_by_id.len(),
        duplicate_records: duplicates,
        input_sha256: digest(input),
        output_sha256: digest(&output),
        sealed: false,
        note: "Validated derived export, not authenticated evidence. Retain raw records and trusted anchors separately; signals require human review.",
    };
    Ok((output, summary))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn fixture() -> Vec<u8> {
        include_bytes!("../examples/observed/alerts.ndjson").to_vec()
    }

    #[test]
    fn captured_export_is_replayable_and_duplicates_are_explicit() {
        let input = fixture();
        let (out, summary) = prepare(&input).unwrap();
        assert_eq!(summary.input_records, 8);
        assert_eq!(summary.unique_documents, 8);
        let (again, replay) = prepare(&out).unwrap();
        assert_eq!(again, out);
        assert_eq!(summary.output_sha256, replay.output_sha256);
        let (deduped, replay) = prepare(&[input.clone(), input].concat()).unwrap();
        assert_eq!(deduped, out);
        assert_eq!(replay.input_records, 16);
        assert_eq!(replay.duplicate_records, 8);
    }

    #[test]
    fn empty_export_is_explicitly_zero_but_blank_lines_are_errors() {
        let (out, summary) = prepare(b"").unwrap();
        assert!(out.is_empty());
        assert_eq!(summary.unique_documents, 0);
        for invalid in [b"\n".as_slice(), b" \r\n", b"[]", b"null", b"\xff", b"{}"] {
            assert!(prepare(invalid).is_err());
        }
    }

    #[test]
    fn byte_and_record_limits_are_enforced_before_unbounded_work() {
        assert!(prepare(&vec![b' '; MAX_INPUT_BYTES + 1]).is_err());
        assert!(prepare(&vec![b' '; MAX_RECORD_BYTES + 1]).is_err());
        let input = fixture();
        let first = input.split_inclusive(|b| *b == b'\n').next().unwrap();
        let oversized = first.repeat(MAX_RECORDS + 1);
        assert!(oversized.len() <= MAX_INPUT_BYTES);
        assert!(prepare(&oversized)
            .unwrap_err()
            .to_string()
            .contains("record limit"));
    }
}
